                    const job = $.let(perm.get(i));
                    $.assign(cumulative_time, cumulative_time.add(durations.get(job)));
                    $.assign(total_cost, total_cost.add(values.get(job).multiply(cumulative_time)));
                });
                // Negate to minimize (iterative maximizes)
