            random_state: variant('some', 42n),
            mode: variant('some', variant('swap', null)),
        });

        const result = $.let(Optimization.iterative(objective, spaces, config));

        // Optimal WSPT order: job3(3s), job1(5s), job0(10s), job2(20s) → cost = -188.0
